@Composable
fun TaskList(tasks: List<Task>, state: LazyListState = rememberLazyListState()) {
  LazyColumn(state = state) {
    items(
      items = tasks,
      key = { it.id },                      // stable identity
      contentType = { it.kind },            // reuse across the same kind
    ) { task ->
      TaskRow(task, Modifier.animateItem())  // animates moves, needs the key
    }
  }
}

@Composable
private fun TaskRow(task: Task, modifier: Modifier = Modifier) {
  var expanded by rememberSaveable { mutableStateOf(false) }  // follows the key
  Column(modifier.clickable { expanded = !expanded }) {
    Text(task.title)
    if (expanded) Text(task.details)
  }
}

// Paging without recomposing on every pixel of scroll
@Composable
fun PagedList(state: LazyListState, onLoadMore: () -> Unit) {
  LaunchedEffect(state) {
    snapshotFlow { state.layoutInfo.visibleItemsInfo.lastOrNull()?.index }
      .distinctUntilChanged()
      .collect { last -> if (last != null && last >= state.layoutInfo.totalItemsCount - 5) onLoadMore() }
  }
}

