@Composable
fun TwoColumnGrid(modifier: Modifier = Modifier, content: @Composable () -> Unit) {
  Layout(content = content, modifier = modifier) { measurables, constraints ->
    val columnWidth = constraints.maxWidth / 2
    val childConstraints = constraints.copy(
      minWidth = 0,
      maxWidth = columnWidth,
    )
    val placeables = measurables.map { it.measure(childConstraints) }  // once each

    val rowHeights = placeables.chunked(2).map { row -> row.maxOf { it.height } }
    val totalHeight = rowHeights.sum().coerceAtMost(constraints.maxHeight)

    layout(constraints.maxWidth, totalHeight) {
      var y = 0
      placeables.chunked(2).forEachIndexed { rowIndex, row ->
        row.forEachIndexed { column, placeable ->
          placeable.placeRelative(x = column * columnWidth, y = y)
        }
        y += rowHeights[rowIndex]
      }
    }
  }
}

// One child only — a layout modifier is lighter than a Layout
fun Modifier.offsetHalfDown() = layout { measurable, constraints ->
  val placeable = measurable.measure(constraints)
  layout(placeable.width, placeable.height) {
    placeable.placeRelative(0, placeable.height / 2)
  }
}

